package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block.RectangleConstraint;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeNN.
 * Since arrangeNN is protected, we use a Test subclass to expose it.
 */
public class BorderArrangement_arrangeNN_TriageGen2Test {

    private TestableBorderArrangement arrangement;
    private BlockContainer mockContainer;
    private Graphics2D mockGraphics;

    // Subclass to expose the protected method for testing
    private static class TestableBorderArrangement extends BorderArrangement {
        public Size2D callArrangeNN(BlockContainer container, Graphics2D g2) {
            return super.arrangeNN(container, g2);
        }

        // Helper to inject blocks since they are protected fields in BorderArrangement
        public void setTop(Block b) { this.topBlock = b; }
        public void setBottom(Block b) { this.bottomBlock = b; }
        public void setLeft(Block b) { this.leftBlock = b; }
        public void setRight(Block b) { this.rightBlock = b; }
        public void setCenter(Block b) { this.centerBlock = b; }
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        mockContainer = mock(BlockContainer.class);
        mockGraphics = mock(Graphics2D.class);
    }

    @Test
    public void testArrangeNN_AllNull() {
        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);
        assertEquals(0.0, result.getWidth(), 0.001);
        assertEquals(0.0, result.getHeight(), 0.001);
    }

    @Test
    public void testArrangeNN_OnlyTop() {
        Block top = mock(Block.class);
        when(top.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 50));
        arrangement.setTop(top);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(50.0, result.getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(top).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getX(), 0.001);
        assertEquals(0.0, captor.getValue().getY(), 0.001);
        assertEquals(100.0, captor.getValue().getWidth(), 0.001);
        assertEquals(50.0, captor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeNN_OnlyBottom() {
        Block bottom = mock(Block.class);
        when(bottom.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 40));
        arrangement.setBottom(bottom);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(40.0, result.getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(bottom).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getY(), 0.001);
        assertEquals(40.0, captor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeNN_OnlyLeftAndRight() {
        // Testing the h[2] = Math.max(h[2], h[3]) logic and width calculation
        Block left = mock(Block.class);
        when(left.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(30, 60));
        arrangement.setLeft(left);

        Block right = mock(Block.class);
        when(right.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(20, 40));
        arrangement.setRight(right);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        // width = max(0, 0, 30 + 0 + 20) = 50
        // h[2] = max(60, 40) = 60. h[3] = 60. centerHeight = max(60, 60, 0) = 60.
        // height = 0 + 0 + 60 = 60
        assertEquals(50.0, result.getWidth(), 0.001);
        assertEquals(60.0, result.getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> leftCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(left).setBounds(leftCaptor.capture());
        assertEquals(0.0, leftCaptor.getValue().getY(), 0.001);
        assertEquals(60.0, leftCaptor.getValue().getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> rightCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(right).setBounds(rightCaptor.capture());
        assertEquals(50.0 - 20.0, rightCaptor.getValue().getX(), 0.001);
        assertEquals(60.0, rightCaptor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeNN_FullLayout() {
        // Top
        Block top = mock(Block.class);
        when(top.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(200, 50));
        arrangement.setTop(top);

        // Bottom
        Block bottom = mock(Block.class);
        when(bottom.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(150, 30));
        arrangement.setBottom(bottom);

        // Left
        Block left = mock(Block.class);
        when(left.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(40, 100));
        arrangement.setLeft(left);

        // Right
        Block right = mock(Block.class);
        when(right.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(40, 80));
        arrangement.setRight(right);

        // Center
        Block center = mock(Block.class);
        when(center.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(50, 110));
        arrangement.setCenter(center);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        /*
         * Calculations:
         * w[0]=200, w[1]=150, w[2]=40, w[3]=40, w[4]=50
         * h[0]=50, h[1]=30, h[2]=100, h[3]=max(100, 80)=100, h[4]=110
         * 
         * width = max(w[0], w[1], w[2]+w[4]+w[3]) 
         *       = max(200, 150, 40+50+40=130) = 200
         * 
         * centerHeight = max(h[2], h[3], h[4]) 
         *              = max(100, 100, 110) = 110
         * 
         * height = h[0] + h[1] + centerHeight 
         *        = 50 + 30 + 110 = 190
         */
        assertEquals(200.0, result.getWidth(), 0.001);
        assertEquals(190.0, result.getHeight(), 0.001);

        // Verify Top
        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 200.0, 50.0));

        // Verify Bottom: y = height - h[1] = 190 - 30 = 160
        verify(bottom).setBounds(new Rectangle2D.Double(0.0, 160.0, 200.0, 30.0));

        // Verify Left: y = h[0] = 50
        verify(left).setBounds(new Rectangle2D.Double(0.0, 50.0, 40.0, 110.0));

        // Verify Right: x = width - w[3] = 200 - 40 = 160
        verify(right).setBounds(new Rectangle2D.Double(160.0, 50.0, 40.0, 110.0));

        // Verify Center: x = w[2] = 40, y = h[0] = 50, width = 200 - 40 - 40 = 120
        verify(center).setBounds(new Rectangle2D.Double(40.0, 50.0, 120.0, 110.0));
    }
}
